class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        r = 0
        for x in nums:
            r ^= x
        return r

class Solution:
    def majorityElement(self, nums: List[int]) -> int:
        cand, cnt = None, 0
        for x in nums:
            if cnt == 0:
                cand = x
            cnt += 1 if x == cand else -1
        return cand

class Solution:
    def missingNumber(self, nums: List[int]) -> int:
        n = len(nums)
        return n * (n + 1) // 2 - sum(nums)

class Solution:
    def moveZeroes(self, nums: List[int]) -> List[int]:
        w = 0
        for i in range(len(nums)):
            if nums[i] != 0:
                nums[w], nums[i] = nums[i], nums[w]
                w += 1
        return nums

class Solution:
    def plusOne(self, digits: List[int]) -> List[int]:
        for i in range(len(digits) - 1, -1, -1):
            if digits[i] < 9:
                digits[i] += 1
                return digits
            digits[i] = 0
        return [1] + digits

class Solution:
    def isPalindrome(self, s: str) -> bool:
        t = [c.lower() for c in s if c.isalnum()]
        return t == t[::-1]

class Solution:
    def reverse(self, x: int) -> int:
        s = -1 if x < 0 else 1
        r = s * int(str(abs(x))[::-1])
        return r if -2**31 <= r <= 2**31 - 1 else 0

class Solution:
    def romanToInt(self, s: str) -> int:
        v = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
        r = 0
        for i, c in enumerate(s):
            if i + 1 < len(s) and v[c] < v[s[i + 1]]:
                r -= v[c]
            else:
                r += v[c]
        return r

class Solution:
    def isPowerOfTwo(self, n: int) -> bool:
        return n > 0 and n & (n - 1) == 0

class Solution:
    def largestRectangleArea(self, heights: List[int]) -> int:
        st, best = [], 0
        for i, h in enumerate(heights + [0]):
            while st and heights[st[-1]] >= h:
                top = st.pop()
                left = st[-1] + 1 if st else 0
                best = max(best, heights[top] * (i - left))
            st.append(i)
        return best

class Solution:
    def rob(self, nums: List[int]) -> int:
        a = b = 0
        for x in nums:
            a, b = b, max(b, a + x)
        return b

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        INF = amount + 1
        dp = [0] + [INF] * amount
        for a in range(1, amount + 1):
            for c in coins:
                if c <= a and dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
        return dp[amount] if dp[amount] != INF else -1

class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        tails = []
        for x in nums:
            i = bisect.bisect_left(tails, x)
            if i == len(tails):
                tails.append(x)
            else:
                tails[i] = x
        return len(tails)

class Solution:
    def findMin(self, nums: List[int]) -> int:
        l, r = 0, len(nums) - 1
        while l < r:
            m = (l + r) // 2
            if nums[m] > nums[r]:
                l = m + 1
            else:
                r = m
        return nums[l]

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        l, r = 0, len(nums) - 1
        while l <= r:
            m = (l + r) // 2
            if nums[m] == target:
                return m
            if nums[l] <= nums[m]:
                if nums[l] <= target < nums[m]:
                    r = m - 1
                else:
                    l = m + 1
            else:
                if nums[m] < target <= nums[r]:
                    l = m + 1
                else:
                    r = m - 1
        return -1

class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        row = [1] * n
        for _ in range(1, m):
            for j in range(1, n):
                row[j] += row[j - 1]
        return row[-1]

class Solution:
    def numDecodings(self, s: str) -> int:
        a, b = 1, 1 if s[0] != '0' else 0
        for i in range(1, len(s)):
            c = b if s[i] != '0' else 0
            if 10 <= int(s[i - 1:i + 1]) <= 26:
                c += a
            a, b = b, c
        return b

class Solution:
    def countSubstrings(self, s: str) -> int:
        n, r = len(s), 0
        for c in range(2 * n - 1):
            l, h = c // 2, c // 2 + c % 2
            while l >= 0 and h < n and s[l] == s[h]:
                r += 1
                l -= 1
                h += 1
        return r

class Solution:
    def mySqrt(self, x: int) -> int:
        l, r = 0, x
        while l < r:
            m = (l + r + 1) // 2
            if m * m <= x:
                l = m
            else:
                r = m - 1
        return l

class Solution:
    def longestConsecutive(self, nums: List[int]) -> int:
        s, best = set(nums), 0
        for x in s:
            if x - 1 not in s:
                y = x
                while y + 1 in s:
                    y += 1
                best = max(best, y - x + 1)
        return best

class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        cnt = {0: 1}
        s = r = 0
        for x in nums:
            s += x
            r += cnt.get(s - k, 0)
            cnt[s] = cnt.get(s, 0) + 1
        return r

class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        return heapq.nlargest(k, nums)[-1]

class Solution:
    def firstMissingPositive(self, nums: List[int]) -> int:
        n = len(nums)
        for i in range(n):
            while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
                j = nums[i] - 1
                nums[i], nums[j] = nums[j], nums[i]
        for i in range(n):
            if nums[i] != i + 1:
                return i + 1
        return n + 1

class Solution:
    def longestValidParentheses(self, s: str) -> int:
        st, best = [-1], 0
        for i, c in enumerate(s):
            if c == '(':
                st.append(i)
            else:
                st.pop()
                if not st:
                    st.append(i)
                else:
                    best = max(best, i - st[-1])
        return best
